+const { QUESTIONS } = require('../../data/questions');
+const { generateResult } = require('../../utils/result-engine');
+const { track } = require('../../utils/tracking');
+
+Page({
+  data: {
+    questions: QUESTIONS,
+    currentIndex: 0,
+    currentQuestion: QUESTIONS[0],
+    progress: 12.5,
+    answers: {},
+    locked: false
+  },
+
+  onLoad() {
+    track('page_view', { page_name: 'quiz' });
+  },
+
+  selectAnswer(event) {
+    if (this.data.locked) return;
+    const answerId = event.currentTarget.dataset.id;
+    const question = this.data.currentQuestion;
+    const answers = {
+      ...this.data.answers,
+      [question.id]: answerId
+    };
+
+    track('question_answer', {
+      page_name: 'quiz',
+      question_id: question.id,
+      answer_id: answerId
+    });
+
+    this.setData({ answers, locked: true });
+
+    setTimeout(() => {
+      if (this.data.currentIndex >= this.data.questions.length - 1) {
+        this.finishQuiz(answers);
+        return;
+      }
+      this.setQuestion(this.data.currentIndex + 1, answers);
+    }, 180);
+  },
+
+  setQuestion(index, answers) {
+    this.setData({
+      currentIndex: index,
+      currentQuestion: this.data.questions[index],
+      progress: ((index + 1) / this.data.questions.length) * 100,
+      answers: answers || this.data.answers,
+      locked: false
+    });
+  },
+
+  goBackQuestion() {
+    if (this.data.currentIndex === 0) return;
+    this.setQuestion(this.data.currentIndex - 1);
+  },
+
+  exitQuiz() {
+    wx.navigateBack({ delta: 1 });
+  },
+
+  finishQuiz(answers) {
+    const answerIds = this.data.questions.map((question) => answers[question.id]).filter(Boolean);
+    const result = generateResult(answerIds);
+    track('quiz_complete', {
+      page_name: 'quiz',
+      result_type: result.type
+    });
+    wx.redirectTo({
+      url: `/pages/result/result?answers=${encodeURIComponent(answerIds.join(','))}`
+    });
+  }
+});
