const { RESULT_COPY } = require('../data/results');

const RESULT_TYPES = [
  '静音崩溃型',
  '假装在线型',
  '会议耗尽型',
  '下班倒计时型',
  '低电量续航型',
  '周一重启失败型',
  '表面稳定型',
  '已读乱回型'
];

const DIMENSIONS = ['energy', 'pressure', 'social', 'patience', 'escape'];

const ANSWER_WEIGHTS = {
  q1_a: { energy: 4 },
  q1_b: { energy: 2, pressure: 1, social: 1 },
  q1_c: { energy: 0, pressure: 3 },
  q2_a: { energy: 1, escape: 1 },
  q2_b: { pressure: 5 },
  q2_c: { pressure: 4, social: 2 },
  q3_a: { pressure: 2, social: 4 },
  q3_b: { social: 2, patience: 2 },
  q3_c: { social: 2, patience: 1, escape: 3 },
  q4_a: { energy: 1, escape: 3 },
  q4_b: { energy: 1, patience: 2 },
  q4_c: { energy: -1, pressure: 3 },
  q5_a: { energy: 1, patience: 3 },
  q5_b: { pressure: 1, patience: 2 },
  q5_c: { pressure: 1, escape: 5 },
  q6_a: { energy: 1 },
  q6_b: { pressure: 1, social: 2 },
  q6_c: { energy: -1, pressure: 3 },
  q7_a: { pressure: 2 },
  q7_b: { social: 1, patience: 2 },
  q7_c: { social: 5, patience: -1 },
  q8_a: { energy: 1, escape: 1 },
  q8_b: { pressure: 1, patience: 2 },
  q8_c: { energy: -1, pressure: 3 }
};

function createEmptyScores() {
  return DIMENSIONS.reduce((scores, key) => {
    scores[key] = 0;
    return scores;
  }, {});
}

function calculateScores(answerIds) {
  const scores = createEmptyScores();
  for (const answerId of answerIds || []) {
    const weights = ANSWER_WEIGHTS[answerId];
    if (!weights) continue;
    for (const key of DIMENSIONS) {
      scores[key] += weights[key] || 0;
    }
  }
  return scores;
}

function chooseResultType(answerIds, scores) {
  const answers = new Set(answerIds || []);
  if (!answerIds || answerIds.length === 0) return '低电量续航型';

  if (answers.has('q4_a') && answers.has('q7_a') && scores.pressure >= 14) return '周一重启失败型';
  if (answers.has('q3_a') && answers.has('q5_b') && scores.pressure >= 14) return '会议耗尽型';
  if (scores.pressure >= 18 && scores.energy <= 0) return '静音崩溃型';
  if (scores.social >= 9 && scores.patience <= 7) return '已读乱回型';
  if (scores.escape >= 10) return '下班倒计时型';
  if (scores.patience >= 10 && scores.social >= 5 && scores.energy < 5) return '假装在线型';
  if (scores.energy <= 4 && scores.pressure >= 6 && scores.pressure <= 12 && scores.escape <= 3) return '低电量续航型';
  if (scores.energy >= 5 && scores.patience >= 10) return '表面稳定型';
  return '低电量续航型';
}

function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value));
}

function calculateThreshold(type, scores, answerCount) {
  if (!answerCount) return 52;
  const raw = 42 + scores.pressure * 2 + scores.social + scores.escape - scores.energy;
  const typeBoost = {
    静音崩溃型: 12,
    会议耗尽型: 8,
    下班倒计时型: 6,
    周一重启失败型: 7,
    已读乱回型: 5,
    假装在线型: 3,
    表面稳定型: -4,
    低电量续航型: 0
  }[type] || 0;
  return clamp(raw + typeBoost, 38, 96);
}

function pickFirst(items) {
  return Array.isArray(items) && items.length ? items[0] : '';
}

function generateResult(answerIds) {
  const safeAnswers = Array.isArray(answerIds) ? answerIds : [];
  const scores = calculateScores(safeAnswers);
  const type = chooseResultType(safeAnswers, scores);
  const copy = RESULT_COPY[type];
  const score = calculateThreshold(type, scores, safeAnswers.length);

  return {
    type,
    title: type,
    subtitle: copy.subtitle,
    score,
    riskLabel: copy.riskLabel,
    tags: copy.tags,
    advice: pickFirst(copy.advicePool),
    shareTitle: pickFirst(copy.shareTitlePool),
    posterLine: '测测你今天还剩几格电',
    scores
  };
}

module.exports = {
  RESULT_TYPES,
  DIMENSIONS,
  ANSWER_WEIGHTS,
  calculateScores,
  generateResult
};

