import { QUESTIONS, type Dimensions } from "@/data/questions";
import { RESULTS, type ResultType } from "@/data/results";

const ZERO: Dimensions = { energy: 0, chaos: 0, escape: 0, pretend: 0 };

export type Answers = Record<string, string>; // questionId -> optionId

export function tally(answers: Answers): Dimensions {
  const dim: Dimensions = { ...ZERO };
  for (const q of QUESTIONS) {
    const ansId = answers[q.id];
    const opt = q.options.find((o) => o.id === ansId);
    if (!opt) continue;
    for (const k of Object.keys(opt.delta) as (keyof Dimensions)[]) {
      dim[k] += opt.delta[k] ?? 0;
    }
  }
  return dim;
}

// 灏嗙淮搴﹀悜閲忔槧灏勫埌 8 绉嶇粨鏋滀箣涓€
export function computeResult(answers: Answers): ResultType {
  const d = tally(answers);
  const { energy, chaos, escape, pretend } = d;
  const total = energy + chaos + escape + pretend || 1;

  // 涓诲缁村害浼樺厛 + 鏋佺缁勫悎鍒ゅ畾
  if (chaos >= 6 && escape >= 3) return "meltdown";
  if (chaos >= 5 && pretend >= 3) return "performer";
  if (escape >= 6 && energy <= 2) return "drifter";
  if (escape >= 4 && chaos <= 2 && pretend <= 2) return "fish";
  if (pretend >= 5) return "pretender";
  if (energy >= 7) return "energizer";
  if (chaos >= 4) return "ghost";
  // 鍏滃簳锛氳兘閲忎笌鍏跺畠閮戒笉鏋佺 -> balanced
  if (energy / total > 0.35) return "balanced";
  return "ghost";
}

