import { createFileRoute, useNavigate } from "@tanstack/react-router";
import { useEffect, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { QUESTIONS } from "@/data/questions";
import { computeResult, type Answers } from "@/lib/quiz-engine";
import { track } from "@/lib/tracking";

export const Route = createFileRoute("/quiz")({
  head: () => ({
    meta: [
      { title: "答题中 · 今日打工状态机" },
      { name: "description", content: "正在进行今日打工状态测试。" },
    ],
  }),
  component: QuizPage,
});

function QuizPage() {
  const navigate = useNavigate();
  const [idx, setIdx] = useState(0);
  const [answers, setAnswers] = useState<Answers>({});
  const lockRef = useRef(false);

  useEffect(() => {
    track("page_view", { page_name: "quiz" });
  }, []);

  const q = QUESTIONS[idx];
  const total = QUESTIONS.length;
  const progress = ((idx + (answers[q.id] ? 1 : 0)) / total) * 100;

  const handlePick = (optId: string) => {
    if (lockRef.current) return;
    lockRef.current = true;
    const next: Answers = { ...answers, [q.id]: optId };
    setAnswers(next);
    track("question_answer", { question_id: q.id, answer_id: optId });

    setTimeout(() => {
      lockRef.current = false;
      if (idx < total - 1) {
        setIdx(idx + 1);
      } else {
        const type = computeResult(next);
        track("quiz_complete", { result_type: type });
        navigate({ to: "/result/$type", params: { type } });
      }
    }, 180);
  };

  const handlePrev = () => {
    if (idx > 0) setIdx(idx - 1);
  };

  return (
    <div className="min-h-screen bg-gradient-to-b from-sky-50 to-rose-50">
      <div className="mx-auto flex min-h-screen max-w-md flex-col px-6 pt-10 pb-10">
        <div className="flex items-center justify-between text-sm text-neutral-600">
          <button onClick={handlePrev} disabled={idx === 0} className="disabled:opacity-30">
            ← 上一题
          </button>
          <span>
            {idx + 1} / {total}
          </span>
        </div>
        <Progress value={progress} className="mt-3 h-2" />

        <h2 className="mt-10 text-2xl font-bold leading-snug text-neutral-900">
          {q.title}
        </h2>

        <div className="mt-8 flex flex-col gap-3">
          {q.options.map((opt) => {
            const selected = answers[q.id] === opt.id;
            return (
              <Button
                key={opt.id}
                variant="outline"
                onClick={() => handlePick(opt.id)}
                className={`h-auto min-h-14 justify-start whitespace-normal rounded-2xl border-2 px-5 py-4 text-left text-base font-medium transition ${
                  selected
                    ? "border-neutral-900 bg-neutral-900 text-white"
                    : "border-neutral-200 bg-white text-neutral-800 hover:border-neutral-400"
                }`}
              >
                {opt.label}
              </Button>
            );
          })}
