import type { ResultDef } from "@/data/results";

// 在 Canvas 上绘制 750x1334 海报，返回 PNG dataURL
export async function buildPoster(result: ResultDef): Promise<string> {
  const W = 750;
  const H = 1334;
  const canvas = document.createElement("canvas");
  canvas.width = W;
  canvas.height = H;
  const ctx = canvas.getContext("2d");
  if (!ctx) throw new Error("Canvas 不可用");

  // 背景渐变
  const grad = ctx.createLinearGradient(0, 0, W, H);
  grad.addColorStop(0, result.gradient[0]);
  grad.addColorStop(1, result.gradient[1]);
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);

  // 顶部小标识
  ctx.fillStyle = "rgba(255,255,255,0.85)";
  ctx.font = "500 28px system-ui, -apple-system, 'PingFang SC', sans-serif";
  ctx.textAlign = "center";
  ctx.fillText("今日打工状态机", W / 2, 110);

  // emoji
  ctx.font = "180px system-ui, 'Apple Color Emoji', 'Segoe UI Emoji'";
  ctx.fillText(result.emoji, W / 2, 320);

  // 状态名
  ctx.fillStyle = "#1a1a1a";
  ctx.font = "700 72px system-ui, -apple-system, 'PingFang SC', sans-serif";
  ctx.fillText(result.name, W / 2, 440);

  // 发疯阈值
  ctx.fillStyle = "rgba(0,0,0,0.7)";
  ctx.font = "500 34px system-ui, -apple-system, 'PingFang SC', sans-serif";
  ctx.fillText(`发疯阈值 ${result.threshold} / 100`, W / 2, 510);

  // 阈值进度条
  const barX = 100;
  const barY = 550;
  const barW = W - 200;
  const barH = 18;
  ctx.fillStyle = "rgba(255,255,255,0.5)";
  roundRect(ctx, barX, barY, barW, barH, 9);
  ctx.fill();
  ctx.fillStyle = "#1a1a1a";
  roundRect(ctx, barX, barY, (barW * result.threshold) / 100, barH, 9);
  ctx.fill();

  // 标签
  ctx.font = "500 30px system-ui, -apple-system, 'PingFang SC', sans-serif";
  let tx = W / 2;
  let ty = 660;
  const tags = result.tags.map((t) => `#${t}`).join("  ");
  ctx.fillStyle = "rgba(0,0,0,0.75)";
  ctx.fillText(tags, tx, ty);

  // 今日建议（自动换行）
  ctx.font = "400 34px system-ui, -apple-system, 'PingFang SC', sans-serif";
  ctx.fillStyle = "#1a1a1a";
  ctx.textAlign = "left";
  const adviceLabel = "今日建议";
  ctx.font = "700 32px system-ui, -apple-system, 'PingFang SC', sans-serif";
  ctx.fillText(adviceLabel, 90, 800);
  ctx.font = "400 36px system-ui, -apple-system, 'PingFang SC', sans-serif";
  wrapText(ctx, result.advice, 90, 860, W - 180, 52);

  // 底部水印
  ctx.textAlign = "center";
  ctx.fillStyle = "rgba(0,0,0,0.55)";
  ctx.font = "400 24px system-ui, -apple-system, 'PingFang SC', sans-serif";
  ctx.fillText("仅供娱乐 · 不构成任何建议", W / 2, H - 90);
  ctx.fillStyle = "rgba(0,0,0,0.4)";
  ctx.font = "400 22px system-ui, -apple-system, 'PingFang SC', sans-serif";
  ctx.fillText("今日打工状态机", W / 2, H - 50);

  return canvas.toDataURL("image/png");
}

function roundRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
) {
  ctx.beginPath();
  ctx.moveTo(x + r, y);
  ctx.arcTo(x + w, y, x + w, y + h, r);
  ctx.arcTo(x + w, y + h, x, y + h, r);
  ctx.arcTo(x, y + h, x, y, r);
  ctx.arcTo(x, y, x + w, y, r);
  ctx.closePath();
}

function wrapText(
  ctx: CanvasRenderingContext2D,
  text: string,
  x: number,
  y: number,
  maxWidth: number,
  lineHeight: number,
) {
  const chars = Array.from(text);
  let line = "";
  let curY = y;
  for (const ch of chars) {
    const test = line + ch;
    if (ctx.measureText(test).width > maxWidth && line.length > 0) {
      ctx.fillText(line, x, curY);
      line = ch;
      curY += lineHeight;
    } else {
      line = test;
    }
  }
  if (line) ctx.fillText(line, x, curY);
}

export function downloadDataUrl(dataUrl: string, filename: string) {
  const a = document.createElement("a");
  a.href = dataUrl;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  document.body.removeChild(a);
}

