import type { ThemeId } from "@/data/questions";
import type { ResultType } from "@/data/results";

export type LocalState = {
  lastTestDate?: string;
  lastResultId?: ResultType;
  unlockedResultIds: ResultType[];
  lastThemeId?: ThemeId;
};

const KEY = "work_state_machine_v02";

export function getLocalState(): LocalState {
  if (typeof window === "undefined") return { unlockedResultIds: [] };
  try {
    const raw = window.localStorage.getItem(KEY);
    if (!raw) return { unlockedResultIds: [] };
    const parsed = JSON.parse(raw) as LocalState;
    return {
      ...parsed,
      unlockedResultIds: Array.isArray(parsed.unlockedResultIds) ? parsed.unlockedResultIds : [],
    };
  } catch {
    return { unlockedResultIds: [] };
  }
}

export function saveResultToLocalState(resultId: ResultType, themeId: ThemeId) {
  if (typeof window === "undefined") return;
  const current = getLocalState();
  const unlocked = new Set<ResultType>(current.unlockedResultIds);
  unlocked.add(resultId);
  const next: LocalState = {
    lastTestDate: todayKey(),
    lastResultId: resultId,
    unlockedResultIds: [...unlocked],
    lastThemeId: themeId,
  };
  window.localStorage.setItem(KEY, JSON.stringify(next));
}

export function hasTestedToday(state = getLocalState()) {
  return state.lastTestDate === todayKey() && Boolean(state.lastResultId);
}

export function todayKey(date = new Date()) {
  return `${date.getFullYear()}-${date.getMonth() + 1}-${date.getDate()}`;
}

