          <div className="flex items-center justify-between text-xs font-bold text-[#6B7280]">
            <span>{progressStage}</span>
            <span>
              {idx + 1} / {total}
            </span>
          </div>
          <Progress value={progress} className="mt-3 h-2 bg-[#E8DFCF]" />
          <div className="mt-5 rounded-md bg-[#F7EEDC] px-3 py-2 text-xs font-semibold">
            {theme.name} · 单次随机抽 8 题
