              const selected = answers[q.id] === opt.id;
              return (
                <Button
                  key={opt.id}
                  variant="outline"
                  onClick={() => handlePick(opt.id)}
                  className={`h-auto min-h-14 justify-start whitespace-normal rounded-md border-2 px-4 py-4 text-left text-base font-bold leading-6 transition ${
                    selected
