import { createFileRoute, Link, useNavigate, useParams, notFound } from "@tanstack/react-router";
import { useEffect, useState } from "react";
import { Button } from "@/components/ui/button";
import { RESULTS, type ResultType } from "@/data/results";
import { isResultType } from "@/lib/quiz-engine";
import { buildPoster, downloadDataUrl } from "@/lib/poster";
import { track } from "@/lib/tracking";
import { toast } from "sonner";

export const Route = createFileRoute("/result/$type")({
  head: ({ params }) => {
    const r = isResultType(params.type) ? RESULTS[params.type as ResultType] : null;
    const title = r ? `我今天是「${r.name}」· 今日打工状态机` : "测试结果 · 今日打工状态机";
    const desc = r ? `发疯阈值 ${r.threshold} / 100。${r.advice}` : "今日打工状态测试结果。";
    return {
      meta: [
        { title },
        { name: "description", content: desc },
        { property: "og:title", content: title },
        { property: "og:description", content: desc },
      ],
    };
  },
  beforeLoad: ({ params }) => {
    if (!isResultType(params.type)) throw notFound();
  },
  component: ResultPage,
  notFoundComponent: () => (
    <div className="flex min-h-screen items-center justify-center p-6 text-center">
      <div>
        <p className="text-neutral-700">没找到这个结果类型</p>
        <Link to="/" className="mt-4 inline-block underline">
          回到首页重测
        </Link>
      </div>
    </div>
  ),
});

function ResultPage() {
  const { type } = useParams({ from: "/result/$type" });
  const navigate = useNavigate();
  const result = RESULTS[type as ResultType];
  const [posterUrl, setPosterUrl] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    track("page_view", { page_name: "result" });
    track("result_view", { result_type: type });
  }, [type]);

  const handleSave = async () => {
    if (busy) return;
    setBusy(true);
    track("poster_save_click", { result_type: type });
    try {
      const url = posterUrl ?? (await buildPoster(result));
      setPosterUrl(url);
      downloadDataUrl(url, `今日打工状态-${result.name}.png`);
      track("poster_save_success", { result_type: type });
      toast.success("海报已保存到本地");
    } catch (e) {
      console.error(e);
      toast.error("保存失败，请长按下方图片保存", {
        description: "iOS 浏览器请长按预览图保存到相册。",
      });
      try {
        const url = await buildPoster(result);
        setPosterUrl(url);
      } catch {
        // ignore
      }
    } finally {
      setBusy(false);
    }
  };

  const handleCopy = async () => {
    track("share_click", { result_type: type, share_channel: "copy_link" });
    const link = `${window.location.origin}/result/${type}`;
    try {
      await navigator.clipboard.writeText(`我今天是「${result.name}」 ${link}`);
      toast.success("分享链接已复制");
    } catch {
      toast.error("复制失败，请手动复制地址栏链接");
    }
  };

  const handleRetry = () => {
    track("retry_click", { result_type: type });
    navigate({ to: "/quiz" });
  };

  return (
    <div className="min-h-screen bg-neutral-50">
      <div className="mx-auto max-w-md px-6 pt-10 pb-10">
        <div
          className="rounded-3xl p-8 shadow-lg"
          style={{
            background: `linear-gradient(135deg, ${result.gradient[0]}, ${result.gradient[1]})`,
          }}
        >
          <div className="text-center">
            <div className="text-7xl">{result.emoji}</div>
            <h1 className="mt-4 text-3xl font-black text-neutral-900">{result.name}</h1>
            <p className="mt-2 text-sm text-neutral-800/80">
              发疯阈值 {result.threshold} / 100
            </p>
            <div className="mx-auto mt-3 h-2 w-full max-w-xs overflow-hidden rounded-full bg-white/50">
              <div
                className="h-full bg-neutral-900"
                style={{ width: `${result.threshold}%` }}
              />
            </div>
            <div className="mt-5 flex flex-wrap justify-center gap-2">
              {result.tags.map((t) => (
                <span
                  key={t}
                  className="rounded-full bg-white/70 px-3 py-1 text-xs font-medium text-neutral-800"
                >
                  #{t}
                </span>
              ))}
            </div>
          </div>
          <div className="mt-6 rounded-2xl bg-white/70 p-4 backdrop-blur">
            <p className="text-xs font-semibold text-neutral-500">今日建议</p>
            <p className="mt-1 text-base leading-relaxed text-neutral-900">{result.advice}</p>
          </div>
        </div>

        <div className="mt-6 flex flex-col gap-3">
          <Button
            onClick={handleSave}
            disabled={busy}
            className="h-12 rounded-2xl bg-neutral-900 text-base font-semibold text-white hover:bg-neutral-800"
          >
            {busy ? "生成中…" : "保存海报"}
          </Button>
          <Button
            onClick={handleCopy}
            variant="outline"
            className="h-12 rounded-2xl border-2 border-neutral-300 bg-white text-base font-semibold text-neutral-900"
          >
            复制分享链接
          </Button>
          <Button
            onClick={handleRetry}
            variant="ghost"
            className="h-12 rounded-2xl text-base font-medium text-neutral-600"
          >
            再测一次
          </Button>
        </div>

        {posterUrl && (
          <div className="mt-8">
            <p className="mb-2 text-center text-xs text-neutral-500">
              长按下图也可保存到相册
            </p>
            <img
              src={posterUrl}
              alt={`${result.name} 海报`}
              className="w-full rounded-2xl shadow"
            />
          </div>
        )}

        <footer className="mt-10 text-center text-xs text-neutral-500">
          <Link to="/about" className="underline-offset-2 hover:underline">
            关于与声明
          </Link>
          <p className="mt-2">本产品为娱乐测试，结果不构成任何心理、医疗、法律或职业建议。</p>
        </footer>
      </div>
    </div>
  );
}

