export const Route = createFileRoute("/result/$type")({
  validateSearch: (search: Record<string, unknown>) => ({
    theme: typeof search.theme === "string" ? search.theme : undefined,
  }),
  head: ({ params }) => {
    const r = isResultType(params.type) ? RESULTS[params.type as ResultType] : null;
    const title = r ? `我今天是「${r.name}」· 今日打工状态机` : "测试结果 · 今日打工状态机";
    const desc = r ? `${r.oneLiner}${r.advice}` : "今日打工状态测试结果。";
    return {
      meta: [
        { title },
        { name: "description", content: desc },
        { property: "og:title", content: title },
        { property: "og:description", content: desc },
      ],
    };
  },
  beforeLoad: ({ params }) => {
    if (!isResultType(params.type)) throw notFound();
  },
  component: ResultPage,
  notFoundComponent: () => (
    <div className="flex min-h-screen items-center justify-center bg-[#FFF8E7] p-6 text-center">
      <div>
        <p className="text-[#4B5563]">没找到这个结果类型</p>
        <Link to="/" className="mt-4 inline-block font-semibold underline">
          回到首页重测
        </Link>
      </div>
    </div>
  ),
});

