  useEffect(() => {
    saveResultToLocalState(result.type, theme.id);
    track("page_view", { page_name: "result", theme_id: theme.id, result_type: type });
    track("result_view", {
      result_type: type,
      theme_id: theme.id,
      result_rarity: result.rarity,
    });
    track("result_card_expose", {
      result_type: type,
      theme_id: theme.id,
      result_rarity: result.rarity,
    });
