import { createFileRoute, Link, useNavigate } from "@tanstack/react-router";
import { ArrowLeft } from "lucide-react";
import { useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@/components/ui/button";
import { Progress } from "@/components/ui/progress";
import { getTheme, pickQuestionsForTheme, computeResult, type Answers } from "@/lib/quiz-engine";
import { saveResultToLocalState } from "@/lib/local-state";
import { track } from "@/lib/tracking";

export const Route = createFileRoute("/quiz")({
  validateSearch: (search: Record<string, unknown>) => ({
    theme: typeof search.theme === "string" ? search.theme : undefined,
  }),
  head: () => ({
    meta: [
      { title: "答题中 · 今日打工状态机" },
      { name: "description", content: "正在生成今日打工状态报告。" },
    ],
  }),
  component: QuizPage,
});

function QuizPage() {
  const navigate = useNavigate();
  const search = Route.useSearch();
  const theme = useMemo(() => getTheme(search.theme), [search.theme]);
  const quizQuestions = useMemo(() => pickQuestionsForTheme(theme.id), [theme.id]);
  const [idx, setIdx] = useState(0);
  const [answers, setAnswers] = useState<Answers>({});
  const [feedback, setFeedback] = useState("");
  const lockRef = useRef(false);

  useEffect(() => {
    track("page_view", { page_name: "quiz", theme_id: theme.id });
  }, [theme.id]);

  const q = quizQuestions[idx];
  const total = quizQuestions.length;
  const progressStage = idx < 3 ? "开机中" : idx < 6 ? "加载人格" : "生成工位档案";
  const progress = ((idx + (answers[q.id] ? 1 : 0)) / total) * 100;

  const handlePick = (optId: string) => {
    if (lockRef.current) return;
    lockRef.current = true;
    const option = q.options.find((item) => item.id === optId);
    const next: Answers = { ...answers, [q.id]: optId };
    setAnswers(next);
    setFeedback(option?.feedback ?? "状态信号已记录");
    track("question_answer", {
      question_id: q.id,
      answer_id: optId,
      theme_id: theme.id,
    });
    track("answer_feedback_view", {
      question_id: q.id,
      theme_id: theme.id,
      feedback: option?.feedback,
    });

    setTimeout(() => {
      setFeedback("");
      lockRef.current = false;
      if (idx < total - 1) {
        setIdx(idx + 1);
      } else {
        const type = computeResult(next, quizQuestions);
        saveResultToLocalState(type, theme.id);
        track("quiz_complete", { result_type: type, theme_id: theme.id });
        navigate({ to: "/result/$type", params: { type }, search: { theme: theme.id } });
      }
    }, 820);
  };

  const handlePrev = () => {
    if (lockRef.current) return;
    if (idx > 0) setIdx(idx - 1);
  };

  return (
    <main className="min-h-screen bg-[#FFF8E7] text-[#171717]">
      <div className="mx-auto flex min-h-screen max-w-md flex-col px-5 pt-6 pb-8">
        <div className="flex items-center justify-between text-sm">
          <button
            onClick={handlePrev}
            disabled={idx === 0}
            className="flex items-center gap-1 font-semibold text-[#4B5563] disabled:opacity-30"
          >
            <ArrowLeft className="h-4 w-4" aria-hidden="true" />
            上一题
          </button>
          <Link
            to="/"
            search={{ entry_result: undefined, theme: undefined }}
            className="font-semibold text-[#4B5563]"
          >
            退出
          </Link>
        </div>

        <section className="mt-5 rounded-lg border border-[#171717] bg-[#FFFDF5] p-4 shadow-[5px_5px_0_#171717]">
          <div className="flex items-center justify-between text-xs font-bold text-[#6B7280]">
            <span>{progressStage}</span>
            <span>
              {idx + 1} / {total}
            </span>
          </div>
          <Progress value={progress} className="mt-3 h-2 bg-[#E8DFCF]" />
          <div className="mt-5 rounded-md bg-[#F7EEDC] px-3 py-2 text-xs font-semibold">
            {theme.name} · 单次随机抽 8 题
          </div>

          <h1 className="mt-7 text-2xl font-black leading-snug tracking-normal">{q.title}</h1>

          <div className="mt-7 flex flex-col gap-3">
            {q.options.map((opt) => {
              const selected = answers[q.id] === opt.id;
              return (
                <Button
                  key={opt.id}
                  variant="outline"
                  onClick={() => handlePick(opt.id)}
                  className={`h-auto min-h-14 justify-start whitespace-normal rounded-md border-2 px-4 py-4 text-left text-base font-bold leading-6 transition ${
                    selected
                      ? "border-[#171717] bg-[#171717] text-white"
                      : "border-[#171717] bg-white text-[#171717] hover:bg-[#F7EEDC]"
                  }`}
                >
                  {opt.label}
                </Button>
              );
            })}
          </div>
        </section>

        <div className="mt-5 min-h-12">
          {feedback && (
            <div className="rounded-md border border-[#171717] bg-[#171717] px-4 py-3 text-center text-sm font-bold text-white shadow-[3px_3px_0_#E94B35]">
              轻反馈：{feedback}
            </div>
          )}
        </div>

        <div className="flex-1" />
        <p className="mt-8 text-center text-xs leading-5 text-[#6B7280]">
          娱乐测试，请勿用于真实决策。网络异常也不影响本地生成结果。
        </p>
      </div>
    </main>
  );
}

