      { name: '已读乱回型', desc: '能回消息，但不保证逻辑' }
    ]
  },

  onLoad(options) {
    track('page_view', {
      page_name: 'index',
      source_channel: options.source || 'direct',
      scene: options.scene || ''
    });
  },

  startQuiz() {
    track('quiz_start', { page_name: 'index' });
    wx.navigateTo({ url: '/pages/quiz/quiz' });
  },

  openAbout() {
    wx.navigateTo({ url: '/pages/about/about' });
  }
});

