const { generateResult } = require('../../utils/result-engine');
const { track } = require('../../utils/tracking');

Page({
  data: {
    result: generateResult([])
  },

  onLoad(options) {
    const answerIds = options.answers ? decodeURIComponent(options.answers).split(',').filter(Boolean) : [];
    const result = generateResult(answerIds);
    this.setData({ result });
    track('result_view', {
      page_name: 'result',
      result_type: result.type
    });
  },

  onShareAppMessage() {
    const result = this.data.result;
    track('share_click', {
      page_name: 'result',
      result_type: result.type,
      share_channel: 'app_message'
    });
    return {
      title: result.shareTitle,
      path: `/pages/index/index?source=share&result=${encodeURIComponent(result.type)}`
    };
  },

  shareResult() {
    wx.showShareMenu({
      withShareTicket: true
    });
    wx.showToast({
      title: '点右上角转发',
      icon: 'none'
    });
    track('share_click', {
      page_name: 'result',
      result_type: this.data.result.type,
      share_channel: 'button'
    });
  },

  retryQuiz() {
    track('retry_click', {
      page_name: 'result',
      result_type: this.data.result.type
    });
    wx.redirectTo({ url: '/pages/quiz/quiz' });
  },

  openAbout() {
    wx.navigateTo({ url: '/pages/about/about' });
  },

  savePoster() {
    const result = this.data.result;
    track('poster_save_click', {
      page_name: 'result',
      result_type: result.type
    });

    const ctx = wx.createCanvasContext('posterCanvas', this);
    ctx.setFillStyle('#fffaf0');
    ctx.fillRect(0, 0, 750, 1000);
    ctx.setFillStyle('#151720');
    ctx.fillRect(0, 0, 750, 210);
    ctx.setFillStyle('#d94d32');
    ctx.fillRect(56, 64, 226, 54);
    ctx.setFillStyle('#fffaf0');
    ctx.setFontSize(26);
    ctx.fillText('今日打工状态', 78, 100);
    ctx.setFillStyle('#151720');
    ctx.setFontSize(64);
    ctx.fillText(result.title, 56, 310);
    ctx.setFontSize(30);
    this.drawWrappedText(ctx, result.subtitle, 56, 370, 620, 42);
    ctx.setFontSize(34);
    ctx.fillText(`发疯阈值 ${result.score}%`, 56, 500);
    ctx.setFillStyle('#e8ddca');
    ctx.fillRect(56, 528, 638, 26);
    ctx.setFillStyle('#151720');
    ctx.fillRect(56, 528, Math.round(638 * result.score / 100), 26);
    ctx.setFontSize(28);
    result.tags.forEach((tag, index) => {
      const x = 56 + index * 198;
      ctx.setStrokeStyle('#151720');
      ctx.strokeRect(x, 610, 176, 54);
      ctx.fillText(tag, x + 22, 647);
    });
    ctx.setFillStyle('#f0e6d3');
    ctx.fillRect(56, 720, 638, 142);
    ctx.setFillStyle('#151720');
    ctx.setFontSize(28);
    ctx.fillText('今日建议', 82, 766);
    ctx.setFontSize(30);
    this.drawWrappedText(ctx, result.advice, 82, 815, 580, 40);
    ctx.setFontSize(24);
    ctx.fillText('测测你今天还剩几格电', 56, 936);
    ctx.draw(false, () => {
      wx.canvasToTempFilePath({
        canvasId: 'posterCanvas',
        width: 750,
        height: 1000,
        destWidth: 750,
        destHeight: 1000,
        success: (res) => {
          wx.saveImageToPhotosAlbum({
            filePath: res.tempFilePath,
            success: () => {
              track('poster_save_success', {
                page_name: 'result',
                result_type: result.type
              });
              wx.showToast({ title: '已保存' });
            },
            fail: () => {
              wx.showToast({ title: '保存失败，请检查相册权限', icon: 'none' });
            }
          });
        },
        fail: () => {
          wx.showToast({ title: '海报生成失败，请重试', icon: 'none' });
        }
      }, this);
    });
  },

  drawWrappedText(ctx, text, x, y, maxWidth, lineHeight) {
    let line = '';
    let currentY = y;
    for (const char of text) {
      const testLine = line + char;
      if (ctx.measureText(testLine).width > maxWidth && line) {
        ctx.fillText(line, x, currentY);
        line = char;
        currentY += lineHeight;
      } else {
        line = testLine;
      }
    }
    if (line) ctx.fillText(line, x, currentY);
  }
});

