const cloud = require('wx-server-sdk');

cloud.init({
  env: cloud.DYNAMIC_CURRENT_ENV
});

exports.main = async (event) => {
  const resultType = sanitize(event.resultType || 'low_battery');
  const themeId = sanitize(event.themeId || 'general');
  const scene = `r=${resultType}&t=${themeId}`;

  const response = await cloud.openapi.wxacode.getUnlimited({
    scene,
    page: 'pages/index/index',
    checkPath: false,
    envVersion: 'release',
    width: 280
  });

  const buffer = response.buffer;
  const cloudPath = `share-codes/${resultType}-${themeId}-${Date.now()}.png`;
  const upload = await cloud.uploadFile({
    cloudPath,
    fileContent: buffer
  });

  return {
    fileID: upload.fileID,
    scene
  };
};

function sanitize(input) {
  return String(input)
    .replace(/[^a-zA-Z0-9_-]/g, '')
    .slice(0, 32);
}

